import { describe, it, expect } from "vitest";

function slug(texto: string) { return texto.toLowerCase().replaceAll(" ", "-"); }

describe("slug", () => {
  it("normaliza espacios", () => expect(slug("Re Zero")).toBe("re-zero"));
});

test("valida un formulario", async ({ page }) => {
  await page.goto("/registro");
  await page.getByLabel("Correo").fill("correo-invalido");
  await page.getByRole("button", { name: "Crear cuenta" }).click();
  await expect(page.getByText("Ingresá un correo válido")).toBeVisible();
});

